-- ============================================================================
-- Migration: feature reads honour min_tier on organization overrides
-- Backlog: BACKLOG-3473
--
-- NOT APPLIED TO PRODUCTION BY THIS PR. The apply is a separate step taken on
-- the founder's word. Apply order: this file, then
-- 20260921101757_backlog_3473_transaction_checklists.sql, then
-- 20260921101758_backlog_3473_retire_unused_org_columns.sql.
--
-- What changes
-- ---------------------------------------------------------------------------
--   After this migration, an entry in organization_plans.feature_overrides that
--   turns ON a feature whose min_tier ranks above the organization's plan tier
--   is IGNORED by check_feature_access, get_org_features and
--   broker_get_org_features: they report the plan row (source 'plan', or
--   'default' when the plan has no row for the feature) with
--   override_ignored: true, and nothing errors. The entry stays in the JSON.
--   Overrides that turn a feature OFF are always honoured. To give one
--   organization an above-tier feature, assign a custom-tier plan.
--
--   Writing such an entry is refused at write time: a BEFORE INSERT OR UPDATE
--   OF feature_overrides trigger on organization_plans raises SQLSTATE 23514
--   with the message prefix `feature_override_above_tier:`. It validates only
--   the entries that the write adds or changes, never runs on a write that
--   leaves feature_overrides unchanged (so a plan assignment or a plan
--   downgrade is never blocked by it), and returns at once when the column is
--   NULL or '{}' (the value the first sign-in path writes).
--
--   override_ignored is an extra key, present only when true. Every other key
--   of every response is unchanged.
--
-- Scope of the rule: ALL features that carry a min_tier.
--   To narrow it to transaction_checklists only, un-comment the one marked
--   line in public._override_above_tier below. The three read functions and
--   the trigger all call that one helper, so that one line narrows both.
--
-- Where the function bodies come from
-- ---------------------------------------------------------------------------
--   The three read functions are the LIVE production definitions
--   (pg_get_functiondef, read 2026-09-21), not the repo's latest migration
--   text, with the min_tier guard and the flag added. The live definitions
--   hashed, as md5(pg_get_functiondef(oid)):
--     check_feature_access(uuid, text)  864e0a56a064a02fefb0c6acc707990f
--     get_org_features(uuid)            be09560411aa508b869a523d35931211
--     broker_get_org_features(uuid)     60c63f216f5a10ab804e90f74d7d8284
--   Re-read those hashes on the target database before applying this file. A
--   different hash means the live body changed after this file was written.
--
--   Every line of the three bodies is the live line except the ones that
--   declare, set or read v_blocked. CREATE OR REPLACE keeps each function's
--   owner, grants, volatility, SECURITY DEFINER and search_path.
--
-- Re-runnable: CREATE OR REPLACE FUNCTION / CREATE OR REPLACE TRIGGER, and
-- REVOKE is idempotent. No BEGIN/COMMIT: the caller supplies the transaction.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. The one helper that decides whether an override is above tier.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._override_above_tier(
  p_feature_key text,
  p_min_tier    text,
  p_plan_tier   text,
  p_override    jsonb
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT COALESCE((p_override ->> 'enabled')::boolean, true)
     AND p_min_tier IS NOT NULL
     AND public.tier_rank(p_plan_tier) < public.tier_rank(p_min_tier)
     -- AND p_feature_key = 'transaction_checklists'   -- the narrowing line (see header)
$$;

REVOKE EXECUTE ON FUNCTION public._override_above_tier(text, text, text, jsonb) FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION public._override_above_tier(text, text, text, jsonb) IS
  'BACKLOG-3473: true when an override entry turns ON a feature whose min_tier ranks above the plan tier. Called by check_feature_access, get_org_features, broker_get_org_features and the organization_plans override trigger.';

-- ---------------------------------------------------------------------------
-- 2. check_feature_access -- live body + guard.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.check_feature_access(p_org_id uuid, p_feature_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_feature RECORD;
  v_plan_feature RECORD;
  v_org_plan RECORD;
  v_override JSONB;
  v_result_enabled BOOLEAN;
  v_result_value TEXT;
  v_blocked BOOLEAN := false;
BEGIN
  -- 0. Verify caller is a member of the organization
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN jsonb_build_object('allowed', false, 'error', 'not_authorized');
  END IF;

  -- 1. Get the feature definition
  SELECT * INTO v_feature
  FROM public.feature_definitions
  WHERE key = p_feature_key;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'error', 'unknown_feature', 'feature_key', p_feature_key);
  END IF;

  -- 2. Get the org's plan
  SELECT op.*, p.tier INTO v_org_plan
  FROM public.organization_plans op
  JOIN public.plans p ON p.id = op.plan_id
  WHERE op.organization_id = p_org_id;

  IF NOT FOUND THEN
    -- No plan assigned: use feature default
    RETURN jsonb_build_object(
      'allowed', v_feature.default_value = 'true',
      'value', v_feature.default_value,
      'source', 'default'
    );
  END IF;

  -- 3. Check for per-org override
  v_override := v_org_plan.feature_overrides -> p_feature_key;
  v_blocked := v_override IS NOT NULL
               AND public._override_above_tier(p_feature_key, v_feature.min_tier, v_org_plan.tier, v_override);
  IF v_override IS NOT NULL AND NOT v_blocked THEN
    v_result_enabled := COALESCE((v_override ->> 'enabled')::boolean, true);
    v_result_value := COALESCE(v_override ->> 'value', v_feature.default_value);
    RETURN jsonb_build_object(
      'allowed', v_result_enabled,
      'value', v_result_value,
      'source', 'override'
    );
  END IF;

  -- 4. Check plan-level feature
  SELECT * INTO v_plan_feature
  FROM public.plan_features pf
  WHERE pf.plan_id = v_org_plan.plan_id
    AND pf.feature_id = v_feature.id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'allowed', v_plan_feature.enabled,
      'value', COALESCE(v_plan_feature.value, v_feature.default_value),
      'source', 'plan'
    ) || CASE WHEN v_blocked THEN '{"override_ignored": true}'::jsonb ELSE '{}'::jsonb END;
  END IF;

  -- 5. Feature not explicitly in plan: use default
  RETURN jsonb_build_object(
    'allowed', v_feature.default_value = 'true',
    'value', v_feature.default_value,
    'source', 'default'
  ) || CASE WHEN v_blocked THEN '{"override_ignored": true}'::jsonb ELSE '{}'::jsonb END;
END;
$function$;

-- ---------------------------------------------------------------------------
-- 3. get_org_features -- live body + guard.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_org_features(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_plan RECORD;
  v_has_plan BOOLEAN := false;
  v_result JSONB := '{}';
  v_feature RECORD;
  v_plan_feature RECORD;
  v_override JSONB;
  v_enabled BOOLEAN;
  v_value TEXT;
  v_source TEXT;
  v_blocked BOOLEAN;
BEGIN
  -- Verify caller is a member of the organization
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members
    WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN jsonb_build_object('error', 'not_authorized', 'features', '[]'::jsonb);
  END IF;

  -- Get org's plan
  SELECT op.*, p.name as plan_name, p.tier as plan_tier INTO v_org_plan
  FROM public.organization_plans op
  JOIN public.plans p ON p.id = op.plan_id
  WHERE op.organization_id = p_org_id;

  v_has_plan := FOUND;

  -- Iterate all features
  FOR v_feature IN SELECT * FROM public.feature_definitions ORDER BY sort_order, key
  LOOP
    v_enabled := v_feature.default_value = 'true';
    v_value := v_feature.default_value;
    v_source := 'default';
    v_blocked := false;

    IF v_has_plan THEN
      -- Check per-org override first
      v_override := v_org_plan.feature_overrides -> v_feature.key;
      v_blocked := v_override IS NOT NULL
                   AND public._override_above_tier(v_feature.key, v_feature.min_tier, v_org_plan.plan_tier, v_override);
      IF v_override IS NOT NULL AND NOT v_blocked THEN
        v_enabled := COALESCE((v_override ->> 'enabled')::boolean, true);
        v_value := COALESCE(v_override ->> 'value', v_feature.default_value);
        v_source := 'override';
      ELSE
        -- Check plan-level feature
        SELECT * INTO v_plan_feature
        FROM public.plan_features pf
        WHERE pf.plan_id = v_org_plan.plan_id
          AND pf.feature_id = v_feature.id;

        IF FOUND THEN
          v_enabled := v_plan_feature.enabled;
          v_value := COALESCE(v_plan_feature.value, v_feature.default_value);
          v_source := 'plan';
        END IF;
      END IF;
    END IF;

    v_result := v_result || jsonb_build_object(
      v_feature.key, jsonb_build_object(
        'enabled', v_enabled,
        'value', v_value,
        'value_type', v_feature.value_type,
        'name', v_feature.name,
        'source', v_source
      ) || CASE WHEN v_blocked THEN '{"override_ignored": true}'::jsonb ELSE '{}'::jsonb END
    );
  END LOOP;

  RETURN jsonb_build_object(
    'org_id', p_org_id,
    'plan_name', COALESCE(v_org_plan.plan_name, 'none'),
    'plan_tier', COALESCE(v_org_plan.plan_tier, 'none'),
    'features', v_result
  );
END;
$function$;

-- ---------------------------------------------------------------------------
-- 4. broker_get_org_features -- live body + guard.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.broker_get_org_features(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_plan RECORD;
  v_has_plan BOOLEAN := false;
  v_result JSONB := '{}';
  v_feature RECORD;
  v_plan_feature RECORD;
  v_override JSONB;
  v_enabled BOOLEAN;
  v_value TEXT;
  v_source TEXT;
  v_blocked BOOLEAN;
BEGIN
  -- Only require authentication (no org membership check)
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'org_id', p_org_id,
      'plan_name', 'none',
      'plan_tier', 'none',
      'features', '{}'::jsonb,
      'error', 'not_authenticated'
    );
  END IF;

  -- Get org's plan
  SELECT op.*, p.name as plan_name, p.tier as plan_tier INTO v_org_plan
  FROM public.organization_plans op
  JOIN public.plans p ON p.id = op.plan_id
  WHERE op.organization_id = p_org_id;

  v_has_plan := FOUND;

  -- Iterate all features
  FOR v_feature IN SELECT * FROM public.feature_definitions ORDER BY sort_order, key
  LOOP
    v_enabled := v_feature.default_value = 'true';
    v_value := v_feature.default_value;
    v_source := 'default';
    v_blocked := false;

    IF v_has_plan THEN
      v_override := v_org_plan.feature_overrides -> v_feature.key;
      v_blocked := v_override IS NOT NULL
                   AND public._override_above_tier(v_feature.key, v_feature.min_tier, v_org_plan.plan_tier, v_override);
      IF v_override IS NOT NULL AND NOT v_blocked THEN
        v_enabled := COALESCE((v_override ->> 'enabled')::boolean, true);
        v_value := COALESCE(v_override ->> 'value', v_feature.default_value);
        v_source := 'override';
      ELSE
        SELECT * INTO v_plan_feature
        FROM public.plan_features pf
        WHERE pf.plan_id = v_org_plan.plan_id
          AND pf.feature_id = v_feature.id;

        IF FOUND THEN
          v_enabled := v_plan_feature.enabled;
          v_value := COALESCE(v_plan_feature.value, v_feature.default_value);
          v_source := 'plan';
        END IF;
      END IF;
    END IF;

    v_result := v_result || jsonb_build_object(
      v_feature.key, jsonb_build_object(
        'enabled', v_enabled,
        'value', v_value,
        'value_type', v_feature.value_type,
        'name', v_feature.name,
        'source', v_source
      ) || CASE WHEN v_blocked THEN '{"override_ignored": true}'::jsonb ELSE '{}'::jsonb END
    );
  END LOOP;

  RETURN jsonb_build_object(
    'org_id', p_org_id,
    'plan_name', COALESCE(v_org_plan.plan_name, 'none'),
    'plan_tier', COALESCE(v_org_plan.plan_tier, 'none'),
    'features', v_result
  );
END;
$function$;

-- ---------------------------------------------------------------------------
-- 5. Write-time rejection of an above-tier override entry.
--    Every path that does not raise returns NEW.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._reject_feature_override_above_tier()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_plan_tier text;
  v_key       text;
  v_entry     jsonb;
  v_min_tier  text;
BEGIN
  IF NEW.feature_overrides IS NULL OR NEW.feature_overrides = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.feature_overrides IS NOT DISTINCT FROM OLD.feature_overrides THEN
    RETURN NEW;
  END IF;

  SELECT p.tier INTO v_plan_tier
    FROM public.plans p
   WHERE p.id = NEW.plan_id;

  -- jsonb_each raises 22023 when feature_overrides is not an object.
  FOR v_key, v_entry IN
    SELECT e.key, e.value FROM jsonb_each(NEW.feature_overrides) AS e
  LOOP
    -- Only the entries this write adds or changes are validated.
    IF TG_OP = 'UPDATE'
       AND jsonb_typeof(OLD.feature_overrides) = 'object'
       AND (OLD.feature_overrides -> v_key) IS NOT DISTINCT FROM v_entry THEN
      CONTINUE;
    END IF;

    v_min_tier := NULL;
    SELECT fd.min_tier INTO v_min_tier
      FROM public.feature_definitions fd
     WHERE fd.key = v_key;

    IF public._override_above_tier(v_key, v_min_tier, v_plan_tier, v_entry) THEN
      RAISE EXCEPTION 'feature_override_above_tier: % requires %; plan tier is %',
        v_key, v_min_tier, COALESCE(v_plan_tier, 'none')
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN NEW;
END
$$;

REVOKE EXECUTE ON FUNCTION public._reject_feature_override_above_tier() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER reject_feature_override_above_tier
  BEFORE INSERT OR UPDATE OF feature_overrides ON public.organization_plans
  FOR EACH ROW
  EXECUTE FUNCTION public._reject_feature_override_above_tier();
